function getStoredLanguage() {
  try {
    const value = localStorage.getItem('webmore-language');
    return value === 'ja' || value === 'en' ? value : null;
  } catch (_) { return null; }
}

function setStoredLanguage(lang) {
  try { localStorage.setItem('webmore-language', lang); } catch (_) {}
}

const originalTextNodes = new WeakMap();
const originalAttributes = new WeakMap();
let originalTitle = document.title;
let currentAppliedLanguage = 'en';
let translationObserver = null;

function normalizeText(value) {
  return value.replace(/\s+/g, ' ').trim();
}

function replaceTrimmed(value, translated) {
  const start = value.search(/\S/);
  const end = value.search(/\s*$/);
  const left = start < 0 ? '' : value.slice(0, start);
  const right = end < 0 ? '' : value.slice(end);
  return left + translated + right;
}

function translateDynamic(text, lang) {
  if (lang !== 'ja') return null;
  const t = normalizeText(text);
  const map = translations.ja;
  if (map[t]) return map[t];

  let m = t.match(/^Results for “(.*)”$/);
  if (m) return `「${m[1]}」の検索結果`;
  m = t.match(/^Joined (.+)$/);
  if (m) return `参加日 ${m[1]}`;
  m = t.match(/^Replies\s+(\d+)$/);
  if (m) return `返信 ${m[1]}`;
  m = t.match(/^(\d+)\s+(post|posts)$/i);
  if (m) return `${m[1]} 件の投稿`;
  m = t.match(/^Favourites\s*\((\d+)\)$/);
  if (m) return `お気に入り（${m[1]}）`;
  m = t.match(/^Archive\s*\((\d+)\)$/);
  if (m) return `アーカイブ（${m[1]}）`;
  m = t.match(/^At least (\d+) characters\./i);
  if (m) return `最低${m[1]}文字。`;
  m = t.match(/^Password must be at least (\d+) characters\.$/i);
  if (m) return `パスワードは最低${m[1]}文字です。`;
  m = t.match(/^New password must be at least (\d+) characters\.$/i);
  if (m) return `新しいパスワードは最低${m[1]}文字です。`;
  m = t.match(/^Last updated:\s*(.*)$/);
  if (m) return `最終更新日：${m[1]}`;
  if (t === 'SITE_CONTACT_EMAIL') return 'SITE_CONTACT_EMAIL';
  return null;
}

function shouldSkipElement(el) {
  return !!el?.closest?.('script,style,noscript,.user-generated,.post-content,.reply-content,.url,[data-no-i18n]');
}

function translateTextNode(node, lang) {
  if (!node.parentElement || shouldSkipElement(node.parentElement)) return;
  if (!originalTextNodes.has(node)) originalTextNodes.set(node, node.nodeValue);
  const original = originalTextNodes.get(node) ?? node.nodeValue;
  if (lang === 'en') {
    if (node.nodeValue !== original) node.nodeValue = original;
    return;
  }
  const translated = translateDynamic(original, lang);
  if (translated !== null) node.nodeValue = replaceTrimmed(original, translated);
}

function translateAttribute(el, attr, lang) {
  const value = el.getAttribute(attr);
  if (value === null || shouldSkipElement(el)) return;
  let attrs = originalAttributes.get(el);
  if (!attrs) { attrs = {}; originalAttributes.set(el, attrs); }
  if (!(attr in attrs)) attrs[attr] = value;
  const original = attrs[attr];
  if (lang === 'en') {
    if (value !== original) el.setAttribute(attr, original);
    return;
  }
  const translated = translateDynamic(original, lang) || translations.ja[normalizeText(original)];
  if (translated) el.setAttribute(attr, translated);
}

function translatePage(lang) {
  currentAppliedLanguage = lang === 'ja' ? 'ja' : 'en';
  document.documentElement.lang = currentAppliedLanguage;
  if (!originalTitle) originalTitle = document.title;
  if (currentAppliedLanguage === 'en') {
    document.title = originalTitle;
  } else {
    const dynamicTitle = translateDynamic(originalTitle, 'ja');
    document.title = dynamicTitle || translations.ja[originalTitle] || originalTitle.replace(/ · Webmore$/, ' · Webmore');
  }

  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const nodes = [];
  let node;
  while ((node = walker.nextNode())) nodes.push(node);
  nodes.forEach((n) => translateTextNode(n, currentAppliedLanguage));

  const attrs = ['placeholder', 'aria-label', 'title', 'value', 'alt'];
  document.querySelectorAll('*').forEach((el) => attrs.forEach((attr) => translateAttribute(el, attr, currentAppliedLanguage)));

  document.body.dataset.lang = currentAppliedLanguage;
  document.querySelectorAll('select[name="language"]').forEach((select) => { select.value = currentAppliedLanguage; });
}

function syncLanguageCookie(lang) {
  const secure = location.protocol === 'https:' ? '; Secure' : '';
  document.cookie = `webmore_lang=${encodeURIComponent(lang)}; Max-Age=31536000; Path=/; SameSite=Lax${secure}`;
}

async function persistLanguage(form, lang) {
  try {
    await fetch(form.action || 'language.php', {
      method: 'POST',
      body: new FormData(form),
      credentials: 'same-origin',
      redirect: 'follow',
      keepalive: true,
      headers: { 'X-Requested-With': 'XMLHttpRequest' }
    });
  } catch (_) {
    // The local cookie still keeps navigation consistent if the background save fails.
  }
}

function liveSwitchLanguage(form, select) {
  const next = select.value === 'ja' ? 'ja' : 'en';
  setStoredLanguage(next);
  syncLanguageCookie(next);
  translatePage(next);
  persistLanguage(form, next);
}

function installLanguagePersistence() {
  const serverLang = document.body?.dataset?.lang === 'ja' ? 'ja' : 'en';
  const localLang = getStoredLanguage();
  const effective = localLang || serverLang;
  setStoredLanguage(effective);
  syncLanguageCookie(effective);
  translatePage(effective);

  document.querySelectorAll('select[name="language"]').forEach((select) => {
    const form = select.form;
    if (!form) return;
    select.value = effective;
    if (form.classList.contains('language-mini')) {
      form.addEventListener('submit', (event) => event.preventDefault());
    }
    select.addEventListener('change', (event) => {
      event.preventDefault();
      liveSwitchLanguage(form, select);
      if (form.closest('#language')) {
        const button = form.querySelector('button[type="submit"], button:not([type])');
        if (button) {
          const originalButton = button.dataset.i18nOriginal || button.textContent;
          button.dataset.i18nOriginal = originalButton;
          button.textContent = currentAppliedLanguage === 'ja' ? '保存しました' : 'Saved';
          window.setTimeout(() => {
            button.textContent = button.dataset.i18nOriginal;
            translatePage(currentAppliedLanguage);
          }, 1800);
        }
      }
    });
  });
}

function installDynamicTranslationObserver() {
  if (translationObserver) translationObserver.disconnect();
  translationObserver = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      mutation.addedNodes.forEach((node) => {
        if (node.nodeType === Node.TEXT_NODE) translateTextNode(node, currentAppliedLanguage);
        else if (node.nodeType === Node.ELEMENT_NODE && !shouldSkipElement(node)) {
          const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
          const nodes = [];
          let child;
          while ((child = walker.nextNode())) nodes.push(child);
          nodes.forEach((n) => translateTextNode(n, currentAppliedLanguage));
          ['placeholder','aria-label','title','value','alt'].forEach((attr) => {
            node.querySelectorAll?.('*').forEach((el) => translateAttribute(el, attr, currentAppliedLanguage));
            translateAttribute(node, attr, currentAppliedLanguage);
          });
        }
      });
    }
  });
  translationObserver.observe(document.body, { childList: true, subtree: true });
}

function installPageBehaviors() {
  const lang = currentAppliedLanguage;
  document.querySelectorAll('input[type="file"]').forEach((input) => {
    input.addEventListener('change', () => {
      const existing = input.parentElement?.querySelector('.file-preview');
      if (existing) existing.remove();
      const file = input.files?.[0];
      if (!file || !file.type.startsWith('image/')) return;
      const preview = document.createElement('img');
      preview.className = 'file-preview';
      preview.alt = lang === 'ja' ? '画像プレビュー' : 'Image preview';
      preview.src = URL.createObjectURL(file);
      input.parentElement?.appendChild(preview);
    });
  });

  document.querySelectorAll('form[data-confirm]').forEach((form) => {
    form.addEventListener('submit', (event) => {
      let message = form.getAttribute('data-confirm') || 'Are you sure?';
      if (currentAppliedLanguage === 'ja') {
        message = message.replace('Delete this post? This also removes its replies and uploaded image.', 'この投稿を削除しますか？返信とアップロード画像も削除されます。')
          .replace('Delete this reply?', 'この返信を削除しますか？')
          .replace('Delete this account and all of its content? This cannot be undone.', 'このアカウントとすべてのコンテンツを削除しますか？元に戻せません。');
      }
      if (!window.confirm(message)) event.preventDefault();
    });
  });
}

document.addEventListener('DOMContentLoaded', () => {
  originalTitle = document.title;
  installLanguagePersistence();
  installDynamicTranslationObserver();
  installPageBehaviors();
});

/* ------------------------------------------------------------
   Webmore micro-interactions
------------------------------------------------------------ */
(function () {
  const reduceMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  const body = document.body;
  const html = document.documentElement;
  html.classList.add('js');

  function updateProgress() {
    const doc = document.documentElement;
    const scrollable = Math.max(1, doc.scrollHeight - window.innerHeight);
    const pct = Math.min(100, Math.max(0, (window.scrollY / scrollable) * 100));
    html.style.setProperty('--scroll-progress', `${pct}%`);
  }

  function createRipple(event, target) {
    if (reduceMotion || !target) return;
    if (getComputedStyle(target).position === 'static') target.style.position = 'relative';
    target.style.overflow = 'hidden';
    const rect = target.getBoundingClientRect();
    const size = Math.max(rect.width, rect.height) * 1.35;
    const ripple = document.createElement('span');
    ripple.className = 'btn-ripple';
    ripple.style.width = `${size}px`;
    ripple.style.height = `${size}px`;
    ripple.style.left = `${(event.clientX || (rect.left + rect.width / 2)) - rect.left - size / 2}px`;
    ripple.style.top = `${(event.clientY || (rect.top + rect.height / 2)) - rect.top - size / 2}px`;
    target.appendChild(ripple);
    window.setTimeout(() => ripple.remove(), 520);
  }

  function sparkFrom(button) {
    if (reduceMotion || !button) return;
    const rect = button.getBoundingClientRect();
    const count = 6;
    for (let i = 0; i < count; i++) {
      const dot = document.createElement('span');
      dot.className = 'action-spark';
      dot.style.left = `${rect.left + rect.width / 2}px`;
      dot.style.top = `${rect.top + rect.height / 2}px`;
      const angle = (Math.PI * 2 * i) / count + Math.random() * .25;
      const distance = 13 + Math.random() * 11;
      dot.style.setProperty('--dx', `${Math.cos(angle) * distance}px`);
      dot.style.setProperty('--dy', `${Math.sin(angle) * distance}px`);
      document.body.appendChild(dot);
      window.setTimeout(() => dot.remove(), 500);
    }
  }

  function showToast(message) {
    if (!message) return;
    const old = document.querySelector('.wm-toast');
    if (old) old.remove();
    const toast = document.createElement('div');
    toast.className = 'wm-toast';
    toast.textContent = message;
    toast.setAttribute('role', 'status');
    document.body.appendChild(toast);
    window.setTimeout(() => {
      toast.classList.add('out');
      window.setTimeout(() => toast.remove(), 220);
    }, 1500);
  }

  function prepareImages() {
    document.querySelectorAll('.card-media img, .file-preview').forEach((img) => {
      if (img.complete) return;
      img.style.opacity = '.55';
      img.addEventListener('load', () => {
        img.style.opacity = '1';
      }, { once: true });
    });
  }

  function installReveal() {
    const items = document.querySelectorAll('.card, .how-item, .format-row, .settings-section, .reply-item');
    if (!items.length || reduceMotion || !('IntersectionObserver' in window)) {
      items.forEach((el) => el.classList.add('wm-inview'));
      return;
    }
    const observer = new IntersectionObserver((entries, obs) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        entry.target.classList.add('wm-inview');
        obs.unobserve(entry.target);
      });
    }, { threshold: 0.08, rootMargin: '0px 0px -30px' });
    items.forEach((el) => observer.observe(el));
  }

  function installButtonFeedback() {
    document.querySelectorAll('.btn').forEach((button) => {
      button.addEventListener('pointerdown', (event) => createRipple(event, button));
    });

    document.querySelectorAll('form.inline-action-form').forEach((form) => {
      form.addEventListener('submit', async (event) => {
        const action = form.querySelector('input[name="action"]')?.value;
        const button = form.querySelector('button.post-action');
        if (!action || !['like', 'favorite', 'archive'].includes(action)) return;
        event.preventDefault();
        if (!button || form.dataset.busy === '1') return;
        form.dataset.busy = '1';
        button.disabled = true;
        const fd = new FormData(form);
        try {
          const response = await fetch(form.action || 'actions.php', {
            method: 'POST',
            body: fd,
            credentials: 'same-origin',
            headers: { 'X-Requested-With': 'XMLHttpRequest', 'Accept': 'application/json' }
          });
          const data = await response.json();
          if (!response.ok || !data.ok) throw new Error('action failed');

          const card = form.closest('[data-post-id]');
          const postId = card?.dataset?.postId;
          if (card && postId) {
            const likeButton = card.querySelector('input[value="like"]')?.closest('form')?.querySelector('button');
            const favoriteButton = card.querySelector('input[value="favorite"]')?.closest('form')?.querySelector('button');
            const archiveButton = card.querySelector('input[value="archive"]')?.closest('form')?.querySelector('button');
            if (likeButton) {
              likeButton.classList.toggle('active', !!data.liked);
              likeButton.innerHTML = `${data.liked ? '♥' : '♡'} <span>${Number(data.likes || 0)}</span>`;
              likeButton.setAttribute('aria-label', data.liked ? 'Unlike post' : 'Like post');
            }
            if (favoriteButton) {
              favoriteButton.classList.toggle('active', !!data.favorited);
              favoriteButton.innerHTML = `${data.favorited ? '★' : '☆'} <span>Favourite</span>`;
              favoriteButton.setAttribute('aria-label', data.favorited ? 'Remove from favourites' : 'Add to favourites');
            }
            if (archiveButton) {
              archiveButton.classList.toggle('active', !!data.archived);
              archiveButton.innerHTML = `${data.archived ? '✓' : '＋'} <span>Archive</span>`;
              archiveButton.setAttribute('aria-label', data.archived ? 'Remove from archive' : 'Add to archive');
            }
          }

          button.classList.add(action === 'like' ? 'favorite-pop' : 'action-pop');
          window.setTimeout(() => button.classList.remove('favorite-pop', 'action-pop'), 430);
          if (action === 'like') sparkFrom(button);
          const message = action === 'favorite'
            ? (data.favorited ? 'Added to favourites.' : 'Removed from favourites.')
            : action === 'archive'
              ? (data.archived ? 'Saved for later.' : 'Removed from archive.')
              : (data.liked ? 'Liked' : 'Unliked');
          showToast(currentAppliedLanguage === 'ja' ? (translations.ja[message] || message) : message);
        } catch (_) {
          showToast(currentAppliedLanguage === 'ja' ? translations.ja['Something went wrong.'] : 'Something went wrong.');
        } finally {
          button.disabled = false;
          form.dataset.busy = '0';
        }
      });
    });

    document.querySelectorAll('form[data-confirm]').forEach((form) => {
      form.addEventListener('submit', (event) => {
        if (form.dataset.confirm === 'Delete this post? This also removes its replies and uploaded image.') {
          let message = form.getAttribute('data-confirm');
          if (currentAppliedLanguage === 'ja') message = 'この投稿を削除しますか？返信とアップロード画像も削除されます。';
          if (!window.confirm(message)) event.preventDefault();
        }
      });
    });

    document.querySelectorAll('.copy-post-link').forEach((button) => {
      button.addEventListener('click', async () => {
        const raw = button.dataset.copyLink;
        if (!raw) return;
        const url = new URL(raw, window.location.href).href;
        try {
          if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(url);
          else {
            const area = document.createElement('textarea');
            area.value = url; area.style.position = 'fixed'; area.style.opacity = '0';
            document.body.appendChild(area); area.select(); document.execCommand('copy'); area.remove();
          }
          showToast(currentAppliedLanguage === 'ja' ? translations.ja.Copied : 'Copied');
        } catch (_) {
          showToast(currentAppliedLanguage === 'ja' ? translations.ja['Something went wrong.'] : 'Something went wrong.');
        }
      });
    });
  }

  function installTinyInteractions() {
    if (reduceMotion || window.matchMedia?.('(pointer: coarse)').matches) return;
    document.querySelectorAll('.btn.accent, .btn.primary').forEach((button) => {
      button.addEventListener('pointermove', (event) => {
        const rect = button.getBoundingClientRect();
        const x = (event.clientX - rect.left) / rect.width - .5;
        const y = (event.clientY - rect.top) / rect.height - .5;
        button.style.transform = `translate(${x * 2}px, ${y * 2}px)`;
      });
      button.addEventListener('pointerleave', () => { button.style.transform = ''; });
    });
  }

  function installPostExtras() {
    document.addEventListener('click', (event) => {
      const image = event.target.closest?.('[data-lightbox]');
      if (!image) return;
      const overlay = document.createElement('div');
      overlay.className = 'wm-lightbox';
      overlay.setAttribute('role', 'dialog');
      overlay.setAttribute('aria-modal', 'true');
      const close = document.createElement('button');
      close.type = 'button'; close.className = 'wm-lightbox-close'; close.textContent = '×';
      close.setAttribute('aria-label', currentAppliedLanguage === 'ja' ? '閉じる' : 'Close');
      const full = document.createElement('img');
      full.src = image.currentSrc || image.src;
      full.alt = image.alt || '';
      overlay.append(close, full);
      const remove = () => { overlay.remove(); document.removeEventListener('keydown', onKey); };
      const onKey = (e) => { if (e.key === 'Escape') remove(); };
      close.addEventListener('click', remove);
      overlay.addEventListener('click', (e) => { if (e.target === overlay) remove(); });
      document.addEventListener('keydown', onKey);
      document.body.appendChild(overlay);
      close.focus();
    });

    document.querySelectorAll('.action-menu').forEach((menu) => {
      menu.addEventListener('toggle', () => {
        if (!menu.open) return;
        document.querySelectorAll('.action-menu[open]').forEach((other) => {
          if (other !== menu) other.removeAttribute('open');
        });
      });
    });
  }

  function start() {
    body.classList.add('is-ready');
    updateProgress();
    prepareImages();
    installReveal();
    installButtonFeedback();
    installTinyInteractions();
    installPostExtras();
  }

  window.addEventListener('scroll', updateProgress, { passive: true });
  window.addEventListener('resize', updateProgress, { passive: true });
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start, { once: true });
  } else {
    start();
  }
})();
